type PlusAdImageProps = {
  accessibilityLabel?: string;
  width?: string | number;
};

/** Strollia Plus機能比較広告のSVG画像。 */
export function PlusAdImage({ accessibilityLabel, width = '100%' }: PlusAdImageProps) {
  return (
    <SvgXml
      accessible
      accessibilityLabel={accessibilityLabel}
      xml={xmlContent}
      width={width}
    />
  );
}
